// react-router.config.ts
import type {Config} from "@react-router/dev/config";
export default {ssr:false} satisfies Config;

// app/routes.ts
import {type RouteConfig,index,route} from "@react-router/dev/routes";
export default [index("routes/home.tsx"),route("books","routes/books.tsx")] satisfies RouteConfig;

// app/routes/home.tsx
import {Link} from "react-router";
export default function Home(){return <main><h1>Reading club</h1><Link to="/books">Open the book list</Link></main>;}

// app/routes/books-layout.tsx
import {Outlet} from "react-router";
export default function BooksLayout(){return <section><h1>Our books</h1><Outlet/></section>;}
// Configure this module as a parent with child routes in app/routes.ts.

// Configure route("books/:slug", "routes/book.tsx") first.
// app/routes/book.tsx
import {useParams} from "react-router";
export default function Book(){const {slug}=useParams();return <h1>Book: {slug}</h1>;}

// app/routes/books.tsx; also create public/books.json as a JSON array.
import {useLoaderData} from "react-router";
export async function clientLoader(){const response=await fetch("/books.json");if(!response.ok)throw new Error("Books could not load");return response.json();}
export default function Books(){const books=useLoaderData<typeof clientLoader>();return <ul>{books.map((book:{id:number;title:string})=><li key={book.id}>{book.title}</li>)}</ul>;}

// Add these exports to a route module that has clientLoader.
export function HydrateFallback(){return <p>Loading the book list...</p>;}
// To require client loading during hydration for this route:
// clientLoader.hydrate = true as const;

// Export from the route module.
import {useRouteError,isRouteErrorResponse,Link} from "react-router";
export function ErrorBoundary(){const error=useRouteError();return <main><h1>We could not open this page</h1><p>{isRouteErrorResponse(error)?`Status ${error.status}`:"Please try again."}</p><Link to="/">Go home</Link></main>;}
